from typing import List, Tuple

def f(N: int, M: int, pairs: List[Tuple[int, int]]) -> int:
    G = [[] for _ in range(N)]
    for s, t in pairs:
        G[s].append(t)
    return sum(len(G[s]) - 1 for s in range(N))

